import{_ as t,a0 as l,w as d,s as p,ao as i,I as n,x as o,a1 as a,A as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"如何在云服务提供商的平台上使用Docker Machine | LCTT x X-CMD","titleTemplate":false,"description":"如何在云服务提供商的平台上使用Docker Machine | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在云服务提供商的平台上使用Docker Machine | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在云服务提供商的平台上使用Docker Machine | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150520 How to Use Docker Machine with a Cloud Provider","title":"如何在云服务提供商的平台上使用Docker Machine","tag":"201506","desc":""},"relativePath":"201506/20150520 How to Use Docker Machine with a Cloud Provider.md","filePath":"[post].md"}'),h={name:"201506/20150520 How to Use Docker Machine with a Cloud Provider.md"};function k(s,e,m,u,g,D){const r=l("Link");return d(),p("div",null,[e[16]||(e[16]=i(`<h1 id="如何在云服务提供商的平台上使用docker-machine" tabindex="-1">如何在云服务提供商的平台上使用Docker Machine <a class="header-anchor" href="#如何在云服务提供商的平台上使用docker-machine" aria-label="Permalink to “如何在云服务提供商的平台上使用Docker Machine”">​</a></h1><p>大家好，今天我们来了解如何使用Docker Machine在各种云服务提供商的平台上部署Docker。Docker Machine是一个可以帮助我们在自己的电脑、云服务提供商的平台以及我们数据中心的机器上创建Docker机器的应用程序。它为创建服务器、在服务器中安装Docker、根据用户需求配置Docker客户端提供了简单的解决方案。驱动API对本地机器、数据中心的虚拟机或者公用云机器都适用。Docker Machine支持Windows、OSX和Linux，并且提供一个独立的二进制文件，可以直接使用。它让我们可以充分利用支持Docker的基础设施的生态环境合作伙伴，并且使用相同的接口进行访问。它让人们可以使用一个命令来简单而迅速地在不同的云平台部署Docker容器。</p><h3 id="_1-安装docker-machine" tabindex="-1">1. 安装Docker Machine <a class="header-anchor" href="#_1-安装docker-machine" aria-label="Permalink to “1. 安装Docker Machine”">​</a></h3><p>Docker Machine可以很好地支持每一种Linux发行版。首先，我们需要从Github网站下载最新版本的。这里我们使用curl来下载目前最新0.2.0版本的Docker Machine。</p><p>在64位操作系统运行：</p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-amd64 &gt; /usr/local/bin/docker-machine
</code></pre><p>在32位操作系统运行：</p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-i386 &gt; /usr/local/bin/docker-machine
</code></pre><p>下载最新版本的Docker Machine并将docker-machine文件放到了/usr/local/bin/后，添加执行权限：</p><pre><code># chmod +x /usr/local/bin/docker-machine
</code></pre><p>完成如上操作后，我们需要确认已经成功安装docker-machine了。可以运行如下命令检查，它会输出系统中docker-machine的版本：</p><pre><code># docker-machine -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/installing-docker-machine.png" alt="Installing Docker Machine"></p><p>要在我们的机器上启用docker命令，需要使用如下命令安装Docker客户端：</p><pre><code>    # curl -L https://get.docker.com/builds/linux/x86_64/docker-latest &gt; /usr/local/bin/docker
    # chmod +x /usr/local/bin/docker
</code></pre><h3 id="_2-创建机器" tabindex="-1">2. 创建机器 <a class="header-anchor" href="#_2-创建机器" aria-label="Permalink to “2. 创建机器”">​</a></h3>`,16)),n("p",null,[e[1]||(e[1]=o("在自己的Linux机器上安装好了Docker Machine之后，我们想要将一个docker虚拟机部署到云服务器上。Docker Machine支持几个流行的云平台，如igital Ocean、Amazon Web Services（AWS）、Microsoft Azure、Google Cloud Computing及其它等等，所以我们可以在不同的平台使用相同的接口来部署Docker。本文中我们会使用digitalocean驱动在Digital Ocean的服务器上部署Docker，--driver选项指定digitalocean驱动，--digitalocean-access-token选项指定",-1)),a(r,{href:"https://cloud.digitalocean.com/settings/applications"},{default:c(()=>[...e[0]||(e[0]=[o("Digital Ocean Control Panel",-1)])]),_:1}),e[2]||(e[2]=o("提供的API Token，命令最后的是我们创建的Docker虚拟机的机器名。运行如下命令：",-1))]),e[17]||(e[17]=i(`<pre><code># docker-machine create --driver digitalocean --digitalocean-access-token &lt;API-Token&gt; linux-dev

# eval &quot;$(docker-machine env linux-dev)&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-digitalocean-cloud.png" alt="Docker Machine Digitalocean Cloud"></p><p><strong>注意</strong>： 这里linux-dev是我们将要创建的机器的名称。<code>&lt;API-Token&gt;</code>是一个安全key，可以在Digtal Ocean Control Panel生成。要找到这个key，我们只需要登录到我们的Digital Ocean Control Panel，然后点击API，再点击 Generate New Token，填写一个名称，选上Read和Write。然后我们就会得到一串十六进制的key，那就是<code>&lt;API-Token&gt;</code>，简单地替换到上边的命令中即可。</p><p>运行如上命令后，我们可以在Digital Ocean Droplet Panel中看到一个具有默认配置的droplet已经被创建出来了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/digitalocean-droplet-panel.png" alt="DigitalOcean Droplet Panel"></p><p>简便起见，docker-machine会使用默认配置来部署Droplet。我们可以通过增加选项来定制我们的Droplet。这里是一些digitalocean相关的选项，我们可以使用它们来覆盖Docker Machine所使用的默认配置。</p><ul><li>--digitalocean-image &quot;ubuntu-14-04-x64&quot; 用于选择Droplet的镜像</li><li>--digitalocean-ipv6 enable 启用IPv6网络支持</li><li>--digitalocean-private-networking enable 启用专用网络</li><li>--digitalocean-region &quot;nyc3&quot; 选择部署Droplet的区域</li><li>--digitalocean-size &quot;512mb&quot; 选择内存大小和部署的类型</li></ul><p>如果你想在其他云服务使用docker-machine，并且想覆盖默认的配置，可以运行如下命令来获取Docker Mackine默认支持的对每种平台适用的参数。</p><pre><code># docker-machine create -h
</code></pre><h3 id="_3-选择活跃主机" tabindex="-1">3. 选择活跃主机 <a class="header-anchor" href="#_3-选择活跃主机" aria-label="Permalink to “3. 选择活跃主机”">​</a></h3><p>部署Droplet后，我们想马上运行一个Docker容器，但在那之前，我们需要检查下活跃主机是否是我们需要的机器。可以运行如下命令查看。</p><pre><code># docker-machine ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-ls.png" alt="Docker Machine List"></p><p>ACTIVE一列有“*”标记的是活跃主机。</p><p>现在，如果我们想将活跃主机切换到需要的主机，运行如下命令：</p><pre><code># docker-machine active linux-dev
</code></pre><p><strong>注意</strong>：这里，linux-dev是机器名，我们打算激活这个机器，并且在其上运行Docker容器。</p><h3 id="_4-运行一个docker容器" tabindex="-1">4. 运行一个Docker容器 <a class="header-anchor" href="#_4-运行一个docker容器" aria-label="Permalink to “4. 运行一个Docker容器”">​</a></h3><p>现在，我们已经选择了活跃主机，就可以运行Docker容器了。可以测试一下，运行一个busybox容器来执行<code>echo hello word</code>命令，这样就可以得到输出：</p><pre><code># docker run busybox echo hello world
</code></pre><p>注意：如果你试图在一个装有32位操作系统的宿主机部署Docker容器，使用SSH来运行docker是个好办法。这样你就可以简单跳过这一步，直接进入下一步。</p><h3 id="_5-ssh到docker机器中" tabindex="-1">5. SSH到Docker机器中 <a class="header-anchor" href="#_5-ssh到docker机器中" aria-label="Permalink to “5. SSH到Docker机器中”">​</a></h3><p>如果我们想在机器或者Droplet上控制之前部署的Docker机器，可以使用docker-machine ssh命令来SSH到机器上：</p><pre><code># docker-machine ssh
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-ssh.png" alt="Docker Machine SSH"></p><p>SSH到机器上之后，我们可以在上边运行任何Docker容器。这里我们运行一个nginx：</p><pre><code># docker run -itd -p 80:80 nginx
</code></pre><p>操作完毕后，我们需要运行exit命令来退出Droplet或者服务器。</p><pre><code># exit
</code></pre><h3 id="_5-删除主机" tabindex="-1">5. 删除主机 <a class="header-anchor" href="#_5-删除主机" aria-label="Permalink to “5. 删除主机”">​</a></h3><p>删除在运行的主机以及它的所有镜像和容器，我们可以使用docker-machine rm命令：</p><pre><code># docker-machine rm linux-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-remove-machine.png" alt="Docker Machine Remove All"></p><p>使用docker-machine ls命令检查是否成功删除了：</p><pre><code># docker-machine ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-remove-check.png" alt="Docker Machine Remove Check"></p><h3 id="_6-在不使用驱动的情况新增一个主机" tabindex="-1">6. 在不使用驱动的情况新增一个主机 <a class="header-anchor" href="#_6-在不使用驱动的情况新增一个主机" aria-label="Permalink to “6. 在不使用驱动的情况新增一个主机”">​</a></h3><p>我们可以在不使用驱动的情况往Docker增加一台主机，只需要一个URL。它可以使用一个已有机器的别名，所以我们就不需要每次在运行docker命令时输入完整的URL了。</p><pre><code>$ docker-machine create --url=tcp://104.131.50.36:2376 custombox
</code></pre><h3 id="_7-管理主机" tabindex="-1">7. 管理主机 <a class="header-anchor" href="#_7-管理主机" aria-label="Permalink to “7. 管理主机”">​</a></h3><p>如果你已经让Docker运行起来了，可以使用简单的<strong>docker-machine stop</strong>命令来停止所有正在运行的主机，如果需要再启动的话可以运行<strong>docker-machine start</strong>：</p><pre><code># docker-machine stop
# docker-machine start
</code></pre><p>你也可以使用如下命令来使用机器名作为参数来将其停止或启动：</p><pre><code>$ docker-machine stop linux-dev
$ docker-machine start linux-dev
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Docker Machine是一个非常棒的工具，可以使用Docker容器快速地部署服务。文中我们使用Digital Ocean Platform作演示，但Docker Machine还支持其他平台，如Amazon Web Service、Google Cloud Computing。使用Docker Machine，快速、安全地在几种不同平台部署Docker容器变得很简单了。因为Docker Machine还是Beta版本，不建议在生产环境使用。如果你有任何问题、建议、反馈，请在下方的评论框中写下来，我们会改进或者更新我们的内容。谢谢！享受吧 😃</p><hr>`,47)),n("p",null,[e[4]||(e[4]=o("via: ",-1)),a(r,{href:"http://linoxide.com/linux-how-to/use-docker-machine-cloud-provider/"},{default:c(()=>[...e[3]||(e[3]=[o("http://linoxide.com/linux-how-to/use-docker-machine-cloud-provider/",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=o("作者：",-1)),a(r,{href:"http://linoxide.com/author/arunp/"},{default:c(()=>[...e[5]||(e[5]=[o("Arun Pyasi",-1)])]),_:1}),e[9]||(e[9]=o(" 译者：",-1)),a(r,{href:"https://github.com/goreliu"},{default:c(()=>[...e[6]||(e[6]=[o("goreliu",-1)])]),_:1}),e[10]||(e[10]=o(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:c(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=o("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:c(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原创翻译，",-1)),a(r,{href:"https://linux.cn/"},{default:c(()=>[...e[12]||(e[12]=[o("Linux中国",-1)])]),_:1}),e[15]||(e[15]=o(" 荣誉推出",-1))])])}const _=t(h,[["render",k]]);export{M as __pageData,_ as default};
